/**
 * Deploy ERC-8004 Identity + Reputation registries to Sepolia
 */
import "dotenv/config";
import { createPublicClient, createWalletClient, http, parseAbi } from "viem";
import { privateKeyToAccount } from "viem/accounts";
import { sepolia } from "viem/chains";

const IDENTITY_ABI = parseAbi([
  "constructor()",
  "function registerAgent(string name, string description, string metadataURI) external returns (uint256 tokenId)",
  "function getAgent(address agent) external view returns (string name, string description, bool registered)",
  "event AgentRegistered(address indexed agent, uint256 indexed tokenId, string name)",
]);

const REPUTATION_ABI = parseAbi([
  "constructor()",
  "function addReputation(address agent, uint256 score, string evidence) external",
  "function getReputation(address agent) external view returns (uint256 score, uint256 attestationCount)",
  "event ReputationAdded(address indexed agent, uint256 score, uint256 newTotal)",
]);

const IDENTITY_BYTECODE = "" as `0x${string}`;

const REPUTATION_BYTECODE = "" as `0x${string}`;

async function main() {
  const privateKey = process.env.AGENT_PRIVATE_KEY as `0x${string}`;
  const rpcUrl = process.env.CHAIN_RPC_URL;

  if (!privateKey || !rpcUrl) {
    console.error("Missing AGENT_PRIVATE_KEY or CHAIN_RPC_URL in .env");
    process.exit(1);
  }

  const account = privateKeyToAccount(privateKey);
  console.log(`Deploying from: ${account.address}`);

  const publicClient = createPublicClient({
    chain: sepolia,
    transport: http(rpcUrl),
  });

  const walletClient = createWalletClient({
    account,
    chain: sepolia,
    transport: http(rpcUrl),
  });

  const balance = await publicClient.getBalance({ address: account.address });
  console.log(`Balance: ${Number(balance) / 1e18} ETH\n`);

  // Deploy IdentityRegistry
  console.log("Deploying IdentityRegistry...");
  const identityHash = await walletClient.deployContract({
    abi: IDENTITY_ABI,
    bytecode: IDENTITY_BYTECODE,
  });
  console.log(`  tx: ${identityHash}`);
  const identityReceipt = await publicClient.waitForTransactionReceipt({ hash: identityHash });
  console.log(`  contract: ${identityReceipt.contractAddress}`);
  console.log(`  gas: ${identityReceipt.gasUsed}\n`);

  // Deploy ReputationRegistry
  console.log("Deploying ReputationRegistry...");
  const reputationHash = await walletClient.deployContract({
    abi: REPUTATION_ABI,
    bytecode: REPUTATION_BYTECODE,
  });
  console.log(`  tx: ${reputationHash}`);
  const reputationReceipt = await publicClient.waitForTransactionReceipt({ hash: reputationHash });
  console.log(`  contract: ${reputationReceipt.contractAddress}`);
  console.log(`  gas: ${reputationReceipt.gasUsed}\n`);

  console.log("=== Add to .env ===");
  console.log(`IDENTITY_REGISTRY=${identityReceipt.contractAddress}`);
  console.log(`REPUTATION_REGISTRY=${reputationReceipt.contractAddress}`);
  console.log(`\nhttps://sepolia.etherscan.io/tx/${identityHash}`);
  console.log(`https://sepolia.etherscan.io/tx/${reputationHash}`);
}

main().catch(console.error);
